// Geometry of candles and histograms (src/bars.js) against measurements of the pixels that Lightweight Charts 5 produces in Chrome
// (the module is written from these measurements, not from the library source). Fixture: test/fixtures/lw-measures-bars.json,
// generated by a measurement bench that is not published (candles: the last 3 of a constant series, various spacings and pixel
// ratios).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { candleWidth, candleParts, histColumns, histGap, barParts, barRects, pointMarker } from '../src/bars.js';

const FX = JSON.parse(readFileSync(new URL('./fixtures/lw-measures-bars.json', import.meta.url), 'utf8'));

test('candles: width, wick and position as LW', () => {
  let checked = 0;
  for (const c of FX.candles) {
    const W = candleWidth(c.sp, c.dpr), parts = candleParts(W, c.dpr, c.sp);
    assert.equal(W % 2, parts.wick % 2, `parity ${c.sp}@${c.dpr}`);
    c.cx.forEach((cx, i) => {
      const wick = c.wick[i];
      assert.deepEqual(wick, [Math.round(cx) - Math.floor(parts.wick / 2), parts.wick], `stoppino ${c.sp}@${c.dpr} #${i}`);
      const g = c.body.find(([a, bw]) => Math.round(cx) >= a && Math.round(cx) < a + bw); // pixel group that contains the candle
      const [x0, w] = g;
      if (w === W) { assert.equal(x0, Math.round(cx) - Math.floor(W / 2), `body ${c.sp}@${c.dpr} #${i}`); checked++; }
      else assert.ok(c.sp * c.dpr - W < 1.5, `touching candles ${c.sp}@${c.dpr}: measured ${w}, computed ${W}`);
    });
  }
  assert.ok(checked > 150, 'pochi confronti diretti: ' + checked);
});

test('candles: width thresholds (measured values)', () => {
  assert.equal(candleWidth(5.7, 1), 3);
  assert.equal(candleWidth(5.8, 1), 5);
  assert.equal(candleWidth(8.5, 1), 7);
  assert.equal(candleWidth(11.1, 1), 9);
  assert.equal(candleWidth(5.7, 2), 8);
  assert.equal(candleWidth(5.8, 2), 10);
  assert.equal(candleWidth(3, 2), 6); // intermediate zone: three CSS pixels
  assert.equal(candleWidth(3, 1.5), 3);
});

test('histogram: columns and gaps as LW', () => {
  for (const c of FX.hist) {
    if (c.sp * c.dpr < 2.5) continue; // below 2.5 pixels per bar the columns merge: covered by the pixel comparison (measurement bench)
    const pitch = c.sp * c.dpr, gap = Math.ceil(pitch) <= 1 ? 0 : Math.max(1, Math.floor(c.dpr));
    const n = 14, extra = n - c.cx.length, cx = new Float64Array(n), adj = new Float64Array(n), l = new Int32Array(n), r = new Int32Array(n);
    for (let j = 0; j < n; j++) { cx[j] = c.cx[0] + (j - extra) * pitch; adj[j] = j; }
    for (let j = extra; j < n; j++) cx[j] = c.cx[j - extra]; // the measured centres (same spacing, but already rounded by the API)
    histColumns(n, cx, adj, pitch, gap, l, r);
    const got = []; for (let j = extra; j < n; j++) got.push([l[j], r[j] - l[j] + 1]);
    assert.deepEqual(got.slice(1), c.runs.slice(1), `histogram ${c.sp}@${c.dpr}`); // the first column depends on the bars before the measured window
  }
});

test('OHLC bars: stem and ticks as LW (252 measurements, DPR 1-4, thin and thick)', () => {
  assert.ok(FX.bars.length >= 250);
  for (const [dpr, sp, thin, stem, left, right] of FX.bars) {
    assert.deepEqual(barParts(sp, dpr, !!thin), { stem, left, right }, `${sp}@${dpr} thin=${thin}`);
  }
});

test('OHLC bars: rectangles (extended stem, ticks inside the stem)', () => {
  const out = new Float32Array(30), outU = new Uint32Array(out.buffer);
  // DPR 1: close on the low → the right tick goes up one row (measured on LW), stem from round(max) to round(min) excluded
  let bars = { n: 1, x: [100], o: [150.4], h: [80], l: [359], c: [359], body: [7] };
  let n = barRects(bars, { stem: 1, left: 2, right: 2 }, out, outU, 0);
  assert.equal(n, 3);
  assert.deepEqual([...out.slice(0, 4)], [100, 80, 101, 359]);
  assert.deepEqual([...out.slice(5, 9)], [98, 150, 100, 151]);
  assert.deepEqual([...out.slice(10, 14)], [101, 358, 103, 359]);
  // DPR 2: stem 2 wide from x - 1, extended by one row at each end, ticks 2 tall
  bars = { n: 1, x: [1185], o: [438.2], h: [160], l: [718], c: [299.6], body: [7] };
  n = barRects(bars, { stem: 2, left: 8, right: 9 }, out, outU, 10);
  assert.deepEqual([...out.slice(0, 4)], [1184, 169, 1186, 729]);
  assert.deepEqual([...out.slice(5, 9)], [1176, 447, 1184, 449]);
  assert.deepEqual([...out.slice(10, 14)], [1186, 309, 1195, 311]);
  // without an open tick (openVisible false)
  assert.equal(barRects(bars, { stem: 2, left: 0, right: 9 }, out, outU, 0), 2);
});

test('candles with small spacing and DPR 1.75/2.5: wick and width as LW', () => {
  assert.ok(FX.candlesMore.length >= 45);
  let isolated = 0;
  for (const c of FX.candlesMore) {
    const W = candleWidth(c.sp, c.dpr), parts = candleParts(W, c.dpr, c.sp);
    c.cx.forEach((cx, i) => {
      const [x0, w] = c.wick[i], exp = Math.round(cx) - Math.floor(parts.wick / 2);
      if (c.sp * c.dpr >= 2 * parts.wick + 1 && w === parts.wick) { assert.equal(x0, exp, `stoppino ${c.sp}@${c.dpr} #${i}`); isolated++; }
      else assert.ok(c.wick.some(([a2, ww]) => a2 <= exp && a2 + ww >= exp + parts.wick), `merged wick ${c.sp}@${c.dpr} #${i}`); // dense bars: the measured groups do not match one to one, it is enough that they contain the expected pixel
    });
    // bodies: the computed width, or wider groups when the candles touch (spacing just above the width)
    for (const [, w] of c.body) assert.ok(w === W || (w > W && c.sp * c.dpr - W < 1.5), `body ${c.sp}@${c.dpr}: measured ${w}, computed ${W}`);
  }
  assert.ok(isolated > 30, 'pochi stoppini isolati: ' + isolated);
});

test('histogram: more DPRs and spacings (1.25, 1.75, 2.5 and small steps), centres along the whole series', () => {
  assert.ok(FX.histMore.length >= 45);
  let checked = 0;
  for (const c of FX.histMore) {
    if (c.sp * c.dpr < 2.5) continue;
    const pitch = c.sp * c.dpr, gap = histGap(pitch, c.dpr);
    const n = 300, extra = n - c.cx.length, cx = new Float64Array(n), adj = new Float64Array(n), l = new Int32Array(n), r = new Int32Array(n);
    for (let j = 0; j < n; j++) { cx[j] = c.cx[0] + (j - extra) * pitch; adj[j] = j; } // the whole series: the narrowest column of the whole chart decides the narrowing
    for (let j = extra; j < n; j++) cx[j] = c.cx[j - extra];
    histColumns(n, cx, adj, pitch, gap, l, r);
    const got = []; for (let j = extra; j < n; j++) got.push([l[j], r[j] - l[j] + 1]);
    assert.deepEqual(got.slice(1), c.runs.slice(1), `histogram ${c.sp}@${c.dpr}`);
    checked++;
  }
  assert.ok(checked > 35);
});

test('point markers: centre and area as LW (36 measurements, DPR 1-4)', () => {
  const { rows } = JSON.parse(readFileSync(new URL('./fixtures/lw-measures-points.json', import.meta.url), 'utf8'));
  assert.equal(rows.length, 36);
  for (const [dpr, lw, rad, [dx, area]] of rows) {
    const m = pointMarker(dpr, lw, rad);
    assert.ok(Math.abs(m.xCorr - dx) < 0.02, `centro x ${dpr}/${lw}/${rad}: ${dx} contro ${m.xCorr}`);
    const exact = Math.PI * m.radius * m.radius;
    assert.ok(Math.abs(exact / area - 1) < 0.09, `area ${dpr}/${lw}/${rad}: ${area} contro ${exact.toFixed(1)}`);
  }
});

test('candles: table of measured thresholds (bodyShare), 81 width transitions', () => {
  const T = JSON.parse(readFileSync(new URL('./fixtures/lw-measures-bodyshare.json', import.meta.url), 'utf8')).pts;
  assert.ok(T.length >= 80);
  let checked = 0;
  for (const [s, sp] of T) {
    // each threshold holds for every integer DPR d for which s·d is an integer value v of the right parity: below the threshold the
    // width is less than v, above it is ≥ v
    for (const d of [1, 2, 3, 4, 5, 6, 7, 8]) {
      const v = Math.round(s * d); if (Math.abs(v - s * d) > 1e-4) continue; if (v % 2 !== Math.max(1, d) % 2) continue;
      if (sp < 4.45) continue; // below 4.5 px the candles touch and the measurement is worth less
      assert.ok(candleWidth(sp + 2e-4, d) >= v, `sopra ${sp}@${d}`);
      assert.ok(candleWidth(sp - 2e-4, d) < v, `sotto ${sp}@${d}`);
      checked++;
    }
  }
  assert.ok(checked >= 150, 'controllate ' + checked);
});
